package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.GenderVO;

class GenderValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of gender of user profile")
  void test_gender_value_holder_assign_plain_value() {
    Object holder = new Object();
    GenderValueHolder<Object> value = new GenderValueHolder<>(holder);
    Assertions.assertSame(holder, value.gender("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getGenderValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getGender().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.genderNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getGenderValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getGender().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of gender of user profile")
  void test_gender_value_holder_assign_value_object() {
    Object holder = new Object();
    GenderValueHolder<Object> value = new GenderValueHolder<>(holder);
    GenderVO vo = GenderVO.from("one");
    Assertions.assertFalse(value.getGenderValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.gender(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGenderValue().orElseThrow());
    Assertions.assertSame(holder, value.gender(Optional.empty()));
    Assertions.assertFalse(value.getGenderValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.gender(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGenderValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of gender of user profile against the original")
  void test_gender_value_holder_read() {
    Object holder = new Object();
    GenderValueHolder<Object> value = new GenderValueHolder<>(holder);
    GenderVO vo = GenderVO.from("one");
    GenderVO other = GenderVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getGenderValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGender(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readGender(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.gender(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGender(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGender(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of gender of user profile")
  void test_gender_value_holder_unset() {
    Object holder = new Object();
    GenderValueHolder<Object> value = new GenderValueHolder<>(holder);
    GenderVO vo = GenderVO.from("one");
    value.gender(vo);
    Assertions.assertSame(holder, value.unsetGenderIfMatches("gender_other"));
    Assertions.assertTrue(value.getGenderValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGenderIfMatches("gender"));
    Assertions.assertFalse(value.getGenderValue().isPresent(),
        "The field name must clear the value");
    value.gender(vo);
    Assertions.assertSame(holder, value.unsetGender());
    Assertions.assertFalse(value.getGenderValue().isPresent(), "Unset must clear the value");
  }
}
